namespace RecipeShare.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public int TotalRatingPoints { get; set; }
    public int RatingCount { get; set; }
    public double AverageRating => RatingCount > 0 ? (double)TotalRatingPoints / RatingCount : 0;
}

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, Tomato sauce, Fresh mozzarella, Fresh basil, Olive oil", Steps = "1. Preheat oven to 475°F\n2. Roll out dough\n3. Spread sauce and add cheese\n4. Bake 10-12 minutes\n5. Top with fresh basil" },
        new() { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Pancetta, Eggs, Parmesan, Black pepper", Steps = "1. Cook pasta al dente\n2. Fry pancetta until crisp\n3. Mix eggs with cheese\n4. Toss hot pasta with pancetta\n5. Stir in egg mixture off heat" },
        new() { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken breast, Yogurt, Tikka spice, Tomato sauce, Cream, Rice", Steps = "1. Marinate chicken in yogurt and spices\n2. Grill or bake chicken\n3. Simmer tomato sauce with spices\n4. Add cream and chicken\n5. Serve over rice" },
        new() { Id = 4, Title = "Vegetable Biryani", Category = "Indian", Ingredients = "Basmati rice, Mixed vegetables, Biryani spices, Yogurt, Fried onions, Saffron", Steps = "1. Par-cook rice with whole spices\n2. Cook vegetables with spices\n3. Layer rice and vegetables\n4. Add saffron milk\n5. Seal and cook on low heat 20 minutes" },
        new() { Id = 5, Title = "Tacos al Pastor", Category = "Mexican", Ingredients = "Pork shoulder, Pineapple, Achiote paste, Corn tortillas, Cilantro, Onion", Steps = "1. Marinate pork in achiote\n2. Grill with pineapple\n3. Slice thin\n4. Warm tortillas\n5. Serve with cilantro and onion" },
        new() { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados, Lime, Cilantro, Red onion, Jalapeño, Tomato, Salt", Steps = "1. Mash avocados\n2. Add lime juice\n3. Fold in diced onion, tomato, jalapeño\n4. Add cilantro and salt\n5. Serve immediately with chips" },
        new() { Id = 7, Title = "Pad Thai", Category = "Asian", Ingredients = "Rice noodles, Shrimp, Eggs, Bean sprouts, Peanuts, Tamarind sauce, Lime", Steps = "1. Soak noodles\n2. Stir-fry shrimp and eggs\n3. Add noodles and sauce\n4. Toss with bean sprouts\n5. Garnish with peanuts and lime" },
        new() { Id = 8, Title = "Miso Ramen", Category = "Asian", Ingredients = "Ramen noodles, Miso paste, Pork broth, Soft-boiled egg, Chashu pork, Green onion, Nori", Steps = "1. Prepare pork broth\n2. Dissolve miso paste in broth\n3. Cook noodles\n4. Assemble bowl with toppings\n5. Serve immediately" },
        new() { Id = 9, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate, Butter, Eggs, Sugar, Flour", Steps = "1. Melt chocolate and butter\n2. Whisk eggs and sugar\n3. Fold in flour and chocolate\n4. Pour into ramekins\n5. Bake at 425°F for 12 minutes" },
        new() { Id = 10, Title = "Tiramisu", Category = "Desserts", Ingredients = "Ladyfingers, Mascarpone, Espresso, Eggs, Sugar, Cocoa powder", Steps = "1. Whip egg yolks with sugar\n2. Fold in mascarpone\n3. Dip ladyfingers in espresso\n4. Layer with cream\n5. Dust with cocoa and chill overnight" },
    };

    private int _nextId = 11;

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            recipe.TotalRatingPoints += stars;
            recipe.RatingCount++;
        }
    }
}

@page "/"

<PageTitle>RecipeShare - Home</PageTitle>

<div class="container">
    <div class="text-center my-5">
        <h1 class="display-4">🍳 RecipeShare</h1>
        <p class="lead">Discover and share delicious recipes from around the world</p>
    </div>

    <h2 class="mb-4">Browse by Category</h2>
    <div class="row g-4">
        @foreach (var category in Categories)
        {
            <div class="col-md-4 col-sm-6">
                <div class="card h-100 shadow-sm">
                    <div class="card-body text-center">
                        <h3 class="card-title">@GetEmoji(category) @category</h3>
                        <p class="card-text text-muted">Explore @category recipes</p>
                        <a href="/recipes/@category" class="btn btn-outline-primary">Browse</a>
                    </div>
                </div>
            </div>
        }
    </div>

    <div class="text-center mt-5">
        <a href="/submit" class="btn btn-success btn-lg">📝 Submit a Recipe</a>
    </div>
</div>

@code {
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private List<string> Categories { get; set; } = new();

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }

    private string GetEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Asian" => "🍜",
        "Desserts" => "🍰",
        _ => "🍽️"
    };
}

@page "/recipes/{Category}"

<PageTitle>@Category Recipes - RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@Category</li>
        </ol>
    </nav>

    <h1 class="mb-4">@Category Recipes</h1>

    @if (Recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes found in this category.</div>
    }
    else
    {
        <div class="row g-4">
            @foreach (var recipe in Recipes)
            {
                <div class="col-md-6">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text text-muted">
                                @if (recipe.RatingCount > 0)
                                {
                                    <span>⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</span>
                                }
                                else
                                {
                                    <span>No ratings yet</span>
                                }
                            </p>
                            <a href="/recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public string Category { get; set; } = string.Empty;
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private List<RecipeShare.Services.Recipe> Recipes { get; set; } = new();

    protected override void OnInitialized()
    {
        Recipes = RecipeService.GetByCategory(Category);
    }
}

@page "/recipe/{Id:int}"

<PageTitle>@(Recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (Recipe is not null)
            {
                <li class="breadcrumb-item"><a href="/recipes/@Recipe.Category">@Recipe.Category</a></li>
                <li class="breadcrumb-item active">@Recipe.Title</li>
            }
        </ol>
    </nav>

    @if (Recipe is null)
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
    else
    {
        <h1>@Recipe.Title</h1>
        <span class="badge bg-secondary mb-3">@Recipe.Category</span>

        <div class="row mt-4">
            <div class="col-md-4">
                <div class="card">
                    <div class="card-header"><strong>Ingredients</strong></div>
                    <div class="card-body">
                        <ul class="list-unstyled mb-0">
                            @foreach (var ingredient in Recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
                            {
                                <li>• @ingredient</li>
                            }
                        </ul>
                    </div>
                </div>
            </div>
            <div class="col-md-8">
                <div class="card">
                    <div class="card-header"><strong>Steps</strong></div>
                    <div class="card-body">
                        @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <p class="mb-2">@step</p>
                        }
                    </div>
                </div>
            </div>
        </div>

        <div class="mt-4">
            <StarRating RecipeId="Recipe.Id" />
        </div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeShare.Services.Recipe? Recipe { get; set; }

    protected override void OnInitialized()
    {
        Recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer

<div class="card mt-3">
    <div class="card-body">
        <h5 class="card-title">Rate this recipe</h5>
        <div class="d-flex align-items-center gap-2">
            @for (int i = 1; i <= 5; i++)
            {
                var star = i;
                <button class="btn btn-link fs-3 p-0 text-decoration-none"
                        @onclick="() => SubmitRating(star)"
                        disabled="@HasRated"
                        title="Rate @star stars">
                    @(star <= HoverStar ? "⭐" : "☆")
                </button>
            }
            @if (HasRated)
            {
                <span class="text-success ms-2">✓ Thanks for rating!</span>
            }
        </div>
        @if (Recipe is not null && Recipe.RatingCount > 0)
        {
            <small class="text-muted">
                Average: @Recipe.AverageRating.ToString("F1") / 5 (@Recipe.RatingCount ratings)
            </small>
        }
    </div>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeShare.Services.Recipe? Recipe { get; set; }
    private int HoverStar { get; set; }
    private bool HasRated { get; set; }

    protected override void OnInitialized()
    {
        Recipe = RecipeService.GetById(RecipeId);
    }

    private void SubmitRating(int stars)
    {
        if (HasRated) return;
        RecipeService.AddRating(RecipeId, stars);
        HoverStar = stars;
        HasRated = true;
        Recipe = RecipeService.GetById(RecipeId);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Services

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1 class="mb-4">📝 Submit a Recipe</h1>

    @if (Submitted)
    {
        <div class="alert alert-success">
            <h4>Recipe submitted successfully!</h4>
            <p>Your recipe "<strong>@Model.Title</strong>" has been added.</p>
            <a href="/recipe/@SubmittedId" class="btn btn-primary">View Recipe</a>
            <button class="btn btn-outline-secondary ms-2" @onclick="Reset">Submit Another</button>
        </div>
    }
    else
    {
        <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="Model.Title" placeholder="e.g., Grandma's Apple Pie" />
                <ValidationMessage For="() => Model.Title" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="Model.Category">
                    <option value="">-- Select a category --</option>
                    <option value="Italian">Italian</option>
                    <option value="Indian">Indian</option>
                    <option value="Mexican">Mexican</option>
                    <option value="Asian">Asian</option>
                    <option value="Desserts">Desserts</option>
                    <option value="Other">Other</option>
                </InputSelect>
                <ValidationMessage For="() => Model.Category" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients</label>
                <InputTextArea id="ingredients" class="form-control" rows="4" @bind-Value="Model.Ingredients"
                    placeholder="List ingredients separated by commas" />
                <ValidationMessage For="() => Model.Ingredients" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps</label>
                <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="Model.Steps"
                    placeholder="Describe each step on a new line" />
                <ValidationMessage For="() => Model.Steps" class="text-danger" />
            </div>

            <button type="submit" class="btn btn-success btn-lg">Submit Recipe</button>
        </EditForm>
    }
</div>

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private RecipeFormModel Model { get; set; } = new();
    private bool Submitted { get; set; }
    private int SubmittedId { get; set; }

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = Model.Title,
            Category = Model.Category,
            Ingredients = Model.Ingredients,
            Steps = Model.Steps
        };
        RecipeService.AddRecipe(recipe);
        SubmittedId = recipe.Id;
        Submitted = true;
    }

    private void Reset()
    {
        Model = new();
        Submitted = false;
    }
}

using System.ComponentModel.DataAnnotations;

